const searchSMEKnowledgeChunks = `-- name: SearchSMEKnowledgeChunks :many
SELECT id, tenant_id, sme_id, submission_id, content, topic, keywords, relevance_score, created_at FROM sme_knowledge_chunks
WHERE sme_id = ANY($1::uuid[])
AND (content ILIKE '%' || $2 || '%' OR topic ILIKE '%' || $2 || '%' OR $2 = ANY(keywords))
ORDER BY relevance_score DESC
LIMIT $3
`

type SearchSMEKnowledgeChunksParams struct {
	SmeIds     []uuid.UUID    `db:"sme_ids" json:"sme_ids"`
	Query      sql.NullString `db:"query" json:"query"`
	LimitCount int32          `db:"limit_count" json:"limit_count"`
}

func (q *Queries) SearchSMEKnowledgeChunks(ctx context.Context, arg SearchSMEKnowledgeChunksParams) ([]SmeKnowledgeChunk, error) {
	rows, err := q.db.QueryContext(ctx, searchSMEKnowledgeChunks, pq.Array(arg.SmeIds), arg.Query, arg.LimitCount)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SmeKnowledgeChunk{}
	for rows.Next() {
		var i SmeKnowledgeChunk
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.SmeID,
			&i.SubmissionID,
			&i.Content,
			&i.Topic,
			pq.Array(&i.Keywords),
			&i.RelevanceScore,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

